\begin{algorithm}
\algname{Algorithm}
\caption{KZG polynomial commitment}
\begin{algorithmic}
\State $\Setup(1^\secpar, d)$: $\tau \getsr \ZZ_p^{*}$; $\mathsf{srs} \gets (g, g^{\tau}, \ldots, g^{\tau^{d}})$; discard $\tau$
\State $\mathsf{Commit}(\mathsf{srs}, f) := g^{f(\tau)} = \prod_{i=0}^{d} (g^{\tau^{i}})^{f_{i}}$
\State $\Open(\mathsf{srs}, C, z, y, f)$: $\psi(X) \gets (f(X) - y)/(X - z)$; $\pi \gets g^{\psi(\tau)}$
\State $\Vrfy(\mathsf{srs}, C, z, y, \pi) := [\, e(C/g^{y}, g) = e(\pi, g^{\tau}/g^{z}) \,]$
\end{algorithmic}
\end{algorithm}
